         helpText: "Select all that apply. Compiled languages are converted to machine code before execution.",
         options: [
             { id: "q1-o1", label: "C", value: "c" },
             { id: "q1-o2", label: "Go", value: "go" },
             { id: "q1-o3", label: "Rust", value: "rust" },
             { id: "q1-o4", label: "JavaScript", value: "js" }
         ],
         correctValues: ["c", "go", "rust"]
     },
     {
         id: "q2",
         question: "Which languages were developed (at least initially) by Microsoft?",
         options: [
             { id: "q2-o1", label: "C#", value: "csharp" },
             { id: "q2-o2", label: "TypeScript", value: "ts" },
             { id: "q2-o3", label: "Java", value: "java" },
             { id: "q2-o4", label: "Python", value: "python" }
         ],
         correctValues: ["csharp", "ts"]
     },
     {
         id: "q3",
         question: "Which of these are commonly used for systems programming?",
         options: [
             { id: "q3-o1", label: "C++", value: "cpp" },
             { id: "q3-o2", label: "Rust", value: "rust" },
             { id: "q3-o3", label: "PHP", value: "php" },
             { id: "q3-o4", label: "Ruby", value: "ruby" }
         ],
         correctValues: ["cpp", "rust"]
     }
 ];

 /**
  * Checkbox Component
  */
 function Checkbox({ id, label, value, name }) {
     const div = document.createElement('div');
     div.className = 'checkbox-option';

     const input = document.createElement('input');
     input.type = 'checkbox';
     input.id = id;
     input.name = name;
     input.value = value;

     const labelElement = document.createElement('label');
     labelElement.htmlFor = id;
     labelElement.textContent = label;

     div.appendChild(input);
     div.appendChild(labelElement);
     return div;
 }

 /**
  * Question Component
  */
 function Question({ questionData }) {
     const fieldContainer = document.createElement('div');
     fieldContainer.className = 'form-field';

     const fieldset = document.createElement('fieldset');
     const helpId = `${questionData.id}-help`;

     if (questionData.helpText) {
         fieldset.setAttribute('aria-describedby', helpId);
     }

     const legend = document.createElement('legend');
     legend.textContent = questionData.question;
     fieldset.appendChild(legend);

     if (questionData.helpText) {
         const helpText = document.createElement('p');
         helpText.id = helpId;
         helpText.className = 'help-text';
         helpText.textContent = questionData.helpText;
         fieldset.appendChild(helpText);
     }

     questionData.options.forEach(option => {
         fieldset.appendChild(Checkbox({
             id: option.id,
             label: option.label,
             value: option.value,
             name: questionData.id
         }));
     });

     fieldContainer.appendChild(fieldset);
     return fieldContainer;
 }

 /**
  * Quiz Component
  */
 function Quiz() {
     const form = document.createElement('form');
     form.id = 'quiz-form';
     form.noValidate = true;

     quizData.forEach(qData => {
         form.appendChild(Question({ questionData: qData }));
     });

     const submitContainer = document.createElement('div');
     submitContainer.className = 'submit-container';

     const submitButton = document.createElement('button');
     submitButton.type = 'submit';
     submitButton.textContent = 'Finish Quiz';
     submitContainer.appendChild(submitButton);

     form.appendChild(submitContainer);

     const resultMessage = document.createElement('div');
     resultMessage.id = 'result-message';
     resultMessage.setAttribute('aria-live', 'polite');
     form.appendChild(resultMessage);

     form.addEventListener('submit', (e) => {
         e.preventDefault();
         const formData = new FormData(form);
         let score = 0;

         quizData.forEach(q => {
             const selected = formData.getAll(q.id);
             const isCorrect = selected.length === q.correctValues.length && 
                               selected.every(val => q.correctValues.includes(val)) &&
                               q.correctValues.every(val => selected.includes(val));
             if (isCorrect) score++;
         });

         resultMessage.textContent = `You scored ${score} out of ${quizData.length}!`;
         resultMessage.className = 'success';
     });

     return form;
 }

 // Initial Render
 const root = document.getElementById('quiz-root');
 root.innerHTML = '';
 root.appendChild(Quiz());

